solution:
function solve(coins, amount) {
  // Koin terbesar lebih dulu.
  const urut = [...coins].sort((a, b) => b - a)
  let sisa = amount
  let jumlah = 0
  for (const c of urut) {
    const k = Math.floor(sisa / c)
    jumlah += k
    sisa -= k * c
  }
  return sisa === 0 ? jumlah : -1
}
